const fs = require("fs");
const path = require("path");
const Babel = require("../js/vendor/babel.min.js");

const root = path.resolve(__dirname, "..");
const outDir = path.join(root, "js", "bundle");
const outFile = path.join(outDir, "app.bundle.js");

const files = [
  "js/components/icons.jsx",
  "js/components/layout.jsx",
  "js/pages/landing.jsx",
  "js/pages/login.jsx",
  "js/pages/dashboard.jsx",
  "js/pages/catalog.jsx",
  "js/pages/module.jsx",
  "js/pages/playground.jsx",
  "js/pages/lab-list.jsx",
  "js/pages/game-list.jsx",
  "js/labs/sorting.jsx",
  "js/labs/binary.jsx",
  "js/labs/logic-gates.jsx",
  "js/labs/advanced-labs.jsx",
  "js/games/games.jsx",
  "js/app.jsx",
];

fs.mkdirSync(outDir, { recursive: true });

const chunks = files.map((file) => {
  const abs = path.join(root, file);
  const source = fs.readFileSync(abs, "utf8");
  const transformed = Babel.transform(source, {
    presets: ["react"],
    sourceType: "script",
    filename: file,
    comments: false,
  }).code;
  return [
    `// ---- ${file} ----`,
    "(function () {",
    transformed,
    `\n//# sourceURL=${file}`,
    "})();",
  ].join("\n");
});

const banner = [
  "/*",
  " * SIGMA browser bundle.",
  " * Generated by scripts/build-jsx-bundle.js from source JSX files.",
  " */",
  "",
].join("\n");

fs.writeFileSync(outFile, banner + chunks.join("\n\n") + "\n");
console.log(`Built ${path.relative(root, outFile)} from ${files.length} JSX files.`);
